// Native OKLab coordinates: L in percent, chroma scaled by 250.
function perceptualRampColor(l,c,h){const angle=h*Math.PI/180,fit=fitLabToSRGB(l,c*Math.cos(angle),c*Math.sin(angle));return labColor(fit.l,fit.a,fit.b).hex;}
function buildPerceptualRamp({family='sequential',hue=250,span=70,chroma=45,count=16,layer='emission',phase=0}){
 const ceiling=layer==='smoke'?84:97,floor=layer==='smoke'?12:7;
 return Array.from({length:count},(_,i)=>{const t=i/(count-1);let l,c,h;
 if(family==='diverging'){const d=Math.abs(2*t-1);l=95-61*d;c=chroma*d**.8;h=t<.5?hue:hue+span;}
 else if(family==='cyclic'){l=68+5*Math.sin(2*Math.PI*t);c=chroma*.78;h=hue+360*t;}
 else if(family==='accent'){l=floor+(ceiling-floor)*t;c=chroma*Math.sin(Math.PI*t)**.65;h=hue+(t<.65?span*t*.35:span+100*(t-.65));}
 else{l=floor+(ceiling-floor)*t;c=chroma*Math.sin(Math.PI*t)**.75;h=hue+span*(t-.5)+phase*Math.sin(Math.PI*t);}
 return {t,hex:perceptualRampColor(l,c,h)};
 });
}
// Inspired by discrimination experiments; this is ΔE OK spacing, not fitted MacAdam ellipses or SDCM.
function perceptualDistance(a,b){return Math.hypot((a.l-b.l)/100,(a.a-b.a)/250,(a.b-b.b)/250);}
function buildDiscriminationRamp(options){
 const count=options.count||16,dense=buildPerceptualRamp({...options,family:'sequential',count:257}),labs=dense.map(k=>{const t=k.t,l=(options.layer==='smoke'?12:7)+(options.layer==='smoke'?72:90)*t,c=(options.chroma??45)*Math.sin(Math.PI*t)**.75,h=((options.hue??250)+(options.span??70)*(t-.5)+(options.phase||0)*Math.sin(Math.PI*t))*Math.PI/180;return fitLabToSRGB(l,c*Math.cos(h),c*Math.sin(h));}),lengths=[0];
 for(let i=1;i<labs.length;i++)lengths.push(lengths[i-1]+perceptualDistance(labs[i-1],labs[i]));
 const total=lengths.at(-1);let cursor=1;
 return Array.from({length:count},(_,i)=>{const t=i/(count-1),target=t*total;while(cursor<lengths.length-1&&lengths[cursor]<target)cursor++;
 const lower=cursor-1,segment=lengths[cursor]-lengths[lower],fraction=segment?(target-lengths[lower])/segment:0;
 const a=labs[lower],b=labs[cursor],l=a.l+(b.l-a.l)*fraction,aa=a.a+(b.a-a.a)*fraction,bb=a.b+(b.b-a.b)*fraction,fit=fitLabToSRGB(l,aa,bb);
 return {t,hex:i===0?dense[0].hex:i===count-1?dense.at(-1).hex:labColor(fit.l,fit.a,fit.b).hex};
 });
}
