// Relative propagation distances for an artistic additive beam-overlap model.
function buildPrismRamp(distance=1,reverse=false){
 const spread=.30*distance,width=.21,centers=[.5+spread,.5,.5-spread];
 return Array.from({length:16},(_,i)=>{const t=i/15,x=reverse?1-t:t,rgb=centers.map(center=>Math.exp(-.5*((x-center)/width)**2)),hex='#'+rgb.map(v=>Math.round(encodeSRGB(v)*255).toString(16).padStart(2,'0')).join('');return {t,hex};});
}
