for(const [id,name,base] of extendedVfxFamilies){for(const variant of ['main','soft']){const colors=variant==='main'?base:base.map(hex=>{const lab=rgbToLab(hex),fit=fitLabToSRGB(18+lab.l*.78,lab.a*.48,lab.b*.48);return labColor(fit.l,fit.a,fit.b).hex;});gradientPresets.push({id:'vfx-trope-'+id+'-'+variant,name:'VFX · '+name+(variant==='soft'?' · Soft':''),category:'Effects',originalCategory:'VFX Tropes',colors,positions:colors.map((_,i)=>i/(colors.length-1)),transition:'smooth',description:'Original '+name+' color ramp. '+(variant==='soft'?'Reduced chroma and softer value range for atmospheric or secondary effects.':'Dark body to bright accent for a readable effect silhouette.')+' Color direction only; geometry, motion and compositing define the final effect.'});}}

// Allocate VFX keys by transition structure; preserve discrete palettes and authored endpoints.
function adaptVfxTemplate(p){
 if(p.transition==='bands'||!p.colors||p.colors.length<2)return;
 const original=p.colors.map((hex,i)=>({...rgbToLab(hex),t:p.positions?.[i]??i/(p.colors.length-1)}));
 const dense=Array.from({length:257},(_,i)=>{const t=i/256;let j=1;while(j<original.length-1&&original[j].t<t)j++;const a=original[j-1],b=original[j],u=Math.max(0,Math.min(1,(t-a.t)/(b.t-a.t||1)));return {t,l:a.l+(b.l-a.l)*u,a:a.a+(b.a-a.a)*u,b:a.b+(b.b-a.b)*u};});
 const soft=p.id.endsWith('-soft')||/vapor|ash|steam|mist|snow|fog|dust|smoke/.test(p.id);
 const tolerance=soft?.035:.014;
 const keys=adaptiveGradient(dense,tolerance);
 p.colors=keys.map(k=>k.hex);p.positions=keys.map(k=>k.t);
}
for(const p of gradientPresets.filter(p=>p.id.startsWith('vfx-classic-')||p.id.startsWith('vfx-trope-')))adaptVfxTemplate(p);
